require_once __DIR__.'/../includes/auth.php';auth_require();require_once __DIR__.'/../includes/listing.php';domain_require('accounting.correct');$error='';$types=['expense'=>['expenses','expenses','Operating expense','مصرف عملیاتی'],'loss'=>['expenses','losses','Inventory loss','ضایعات جنس'],'capital'=>['capital','capital','Capital entry','ثبت سرمایه'],'debt'=>['debts','debts','Standalone debt','طلب یا بدهی جدا']];$entity=is_string($_GET['entity']??$_POST['entity']??null)?($_GET['entity']??$_POST['entity']):'expense';if(!isset($types[$entity]))$entity='expense';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST')try{finance_correct($entity,(int)($_POST['entity_id']??0),(string)($_POST['posting_date']??''),(string)($_POST['reason']??''),(string)($_POST['request_key']??''),!empty($_POST['restore_stock']));redirect(BASE_URL.'modules/corrections.php?entity='.$entity);}catch(Throwable $e){http_response_code(in_array($e->getCode(),[403,429],true)?$e->getCode():422);$error=public_error($e);}
$sorts=['newest'=>['id DESC','Newest first','تازه‌ترین اول'],'oldest'=>['id ASC','Oldest first','قدیمی‌ترین اول']];[$list,$history]=listing_query($pdo,'SELECT * FROM financial_corrections WHERE shop_id=?',[shop_id()],$sorts);$pageTitle=__t('Correct mistaken documents','اصلاح سند اشتباه','د ناسم سند اصلاح');require __DIR__.'/../includes/header.php';?>
<h1><?= sanitize($pageTitle) ?></h1><p><?= __t('Cancel an incorrectly recorded open-period document with a reason and a balanced compensating entry. The source stays in history. Confirm the actual cash/bank balance; this records a correction and does not send money through a bank. Use sales/purchase returns for returned goods. Closed-period entries require an approved current-period journal adjustment.','سند اشتباهِ دورهٔ باز را با دلیل و سند متوازن اصلاح کنید. سند اصلی در تاریخچه حفظ می‌شود. ماندهٔ واقعی صندوق یا بانک را تطبیق کنید؛ این ثبت اصلاحی است و بانک به‌صورت خودکار پول انتقال نمی‌دهد. برای جنس برگشتی از برگشت فروش یا خرید استفاده کنید. سند دورهٔ بسته به تعدیل مجازِ دورهٔ فعلی نیاز دارد.','ناسم سند په دلیل او متوازن اصلاحي سند لغوه کړئ؛ اصلي تاریخ ساتل کېږي.') ?></p>
<?php if($error):?><p class="alert alert-danger" role="alert"><?= sanitize($error) ?></p><?php endif ?>
<section class="card modern-form"><form method="get"><label><?= __t('Document type','نوع سند','د سند ډول') ?><select class="form-control" name="entity"><?php foreach($types as $key=>[$table,$module,$en,$da]):if(!domain_can($module.'.approve'))continue;?><option value="<?= $key ?>" <?= $key===$entity?'selected':'' ?>><?= __t($en,$da,$en) ?></option><?php endforeach ?></select></label><button class="btn btn-primary"><?= __t('Show documents','نمایش اسناد','سندونه وښایئ') ?></button></form></section>
<?php [$table,$module]=$types[$entity];if(domain_can($module.'.approve')):$description=$table==='debts'?'customer_name':($table==='capital'?'source_description':'description');$date=$table==='debts'?'created_at':($table==='capital'?'transaction_date':'expense_date');$extra=$entity==='expense'?" AND (s.expense_type<>'ضرر' OR s.expense_type IS NULL)":($entity==='loss'?" AND s.expense_type='ضرر'":($entity==='debt'?' AND s.sale_id IS NULL':''));$q=$pdo->prepare("SELECT s.id,s.$description AS description,s.$date AS source_date,s.currency_code,".($table==='debts'?'s.total_amount':'s.amount')." AS amount FROM $table s WHERE s.shop_id=? AND NOT EXISTS(SELECT 1 FROM financial_corrections c WHERE c.shop_id=s.shop_id AND c.entity_type=? AND c.entity_id=s.id) $extra ORDER BY s.id DESC LIMIT 250");$q->execute([shop_id(),$entity]);?><section class="card modern-form"><form method="post"><?= csrf_field() ?><input name="action" type="hidden" value="approve_correction"><input name="entity" type="hidden" value="<?= $entity ?>"><input name="request_key" type="hidden" value="<?= bin2hex(random_bytes(16)) ?>"><label><?= __t('Original document','سند اصلی','اصلي سند') ?><select class="form-control" name="entity_id" required><?php foreach($q->fetchAll() as $row):?><option value="<?= (int)$row['id'] ?>"><?= sanitize('#'.$row['id'].' · '.$row['source_date'].' · '.$row['description'].' · '.$row['amount'].' '.$row['currency_code']) ?></option><?php endforeach ?></select></label><label><?= __t('Correction date','تاریخ اصلاح','د اصلاح نېټه') ?><input class="form-control" name="posting_date" type="date" value="<?= date('Y-m-d') ?>" required></label><label><?= __t('Reason for cancellation','دلیل لغو سند اشتباه','د لغوه کولو لامل') ?><textarea class="form-control" name="reason" minlength="5" maxlength="500" required></textarea></label><?php if($entity==='loss'):?><label><input type="checkbox" name="restore_stock" value="1" required> <?= __t('The goods physically exist, are saleable and must be restored to stock.','جنس واقعاً موجود و قابل فروش است و باید دوباره شامل موجودی شود.','توکي په حقیقت کې موجود او د پلور وړ دي.') ?></label><?php endif ?><button class="btn btn-danger"><?= __t('Approve correction','تأیید سند اصلاحی','اصلاح تایید') ?></button></form></section><?php endif ?>
<section class="card modern-form table-responsive"><h2><?= __t('Correction history','تاریخچهٔ اسناد اصلاحی','د اصلاحي سندونو تاریخ') ?></h2><table class="table"><thead><tr><?php foreach([__t('Date','تاریخ','نېټه'),__t('Original document','سند اصلی','اصلي سند'),__t('Reason','دلیل','لامل')] as $label):?><th><?= $label ?></th><?php endforeach ?></tr></thead><tbody><?php foreach($history as $c):?><tr><td><?= sanitize($c['posting_date']) ?></td><td><?= __t($types[$c['entity_type']][2]??$c['entity_type'],$types[$c['entity_type']][3]??$c['entity_type'],$c['entity_type']) ?> #<?= (int)$c['entity_id'] ?></td><td><?= sanitize($c['reason']) ?></td></tr><?php endforeach ?></tbody></table></section>
